// Эшландия — Тирритское восстание; области восстаний — сами восставшие (до Акта о единении); остальное — легионы и ополчение.
// Возвращает функцию: провинция -> { date, key, force, merge, how } или null (не земля Освобождения).
const HOW_RISING = ['горожане открыли ворота восставшим', 'земское собрание взяло власть без единого выстрела', 'имперский гарнизон сдался восставшим', 'староста поднял синий флаг с цепью', 'чиновники бежали ночью, утром здесь уже была коммуна']
const HOW_ARMY = ['взят штурмом', 'сдался без боя при виде знамён', 'гарнизон ушёл ночью, город открыл ворота', 'взят после короткой осады', 'горожане перебили гарнизон до подхода войск']
export function liberation(provs, regionName) {
  const byName = new Map(provs.map((p) => [p.name, p]))
  const pos = (key) => {
    if (key.startsWith('prov:')) return byName.get(key.slice(5))
    const b = REPUBLIC_BATTLES.find((x) => x.id === key)
    return b ? byName.get(b.loc.slice(5)) : null
  }
  const forces = [{ key: 'republic', force: 'Тирритское восстание', regions: ['Эшландия'], pts: [{ ...pos('prov:Тиррит'), date: 976.9 }], speed: 1400, rising: true }]
  for (const [key, name, , region, town, start, merge] of UPRISINGS)
    forces.push({ key, force: name, regions: [region], pts: [{ ...pos(`prov:${town}`), date: start }], speed: 1100, merge, rising: true })
  for (const a of REPUBLIC_ARMIES.filter((x) => x.side === 'Республика')) {
    const pts = []
    for (const [k, y] of a.route) {
      const p = pos(k)
      const date = y ?? REPUBLIC_BATTLES.find((b) => b.id === k)?.year
      if (p && date < 977.9) pts.push({ x: p.x, y: p.y, date })
    }
    forces.push({ key: 'republic', force: a.name, regions: null, pts, speed: 950 })
  }
  const owned = new Set(UPRISINGS.map((u) => u[3]).concat('Эшландия'))
  const hash = (s) => [...String(s)].reduce((h, c) => (Math.imul(h, 31) + c.charCodeAt(0)) >>> 0, 7)
  return (p) => {
    const region = regionName(p)
    if (!CONSTITUENT_REGIONS.includes(region)) return null
    let best = null
    for (const f of forces) {
      if (f.regions ? !f.regions.includes(region) : owned.has(region)) continue
      for (const q of f.pts) {
        const d = q.date + Math.hypot(p.x - q.x, p.y - q.y) / f.speed
        if (!best || d < best.date) best = { date: d, f }
      }
    }
    if (!best) return null
    const date = Math.min(best.date, 977.88)
    const merge = best.f.merge && date < best.f.merge ? best.f.merge : null
    const how = (best.f.rising ? HOW_RISING : HOW_ARMY)[hash(p.id) % 5]
    return { date: Math.round(date * 1000) / 1000, key: merge ? best.f.key : 'republic', force: best.f.force, merge, how }
  }
}
